package dao;
import java.sql.*; import java.util.*; import model.Consulta;
public class ConsultaDAO {
 private static final String CHAVE_AES="chave_saep_2026";
 public boolean inserir(Consulta a){String q="INSERT INTO consulta(dependente_id,data_consulta,horario,motivo) VALUES(?,?,?,?)";try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,a.getDependenteId());s.setDate(2,a.getDataConsulta());s.setTime(3,a.getHorario());s.setString(4,a.getMotivo());return s.executeUpdate()>0;}catch(Exception e){System.out.println("Erro ao inserir consulta: "+e.getMessage());return false;}}
 public boolean atualizar(Consulta a){String q="UPDATE consulta SET dependente_id=?,data_consulta=?,horario=?,motivo=? WHERE id=?";try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,a.getDependenteId());s.setDate(2,a.getDataConsulta());s.setTime(3,a.getHorario());s.setString(4,a.getMotivo());s.setInt(5,a.getId());return s.executeUpdate()>0;}catch(Exception e){System.out.println("Erro ao atualizar consulta: "+e.getMessage());return false;}}
 public boolean excluir(int id){try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement("DELETE FROM consulta WHERE id=?")){s.setInt(1,id);return s.executeUpdate()>0;}catch(Exception e){System.out.println("Erro ao excluir consulta: "+e.getMessage());return false;}}
 public List<Consulta> listarTodos(){List<Consulta> l=new ArrayList<>();String q="SELECT c.id,c.dependente_id,c.data_consulta,c.horario,c.motivo,d.nome dependente,d.data_nascimento,d.sexo,d.alergias,r.nome responsavel,CAST(AES_DECRYPT(r.cpf,?) AS CHAR) cpf_responsavel,r.telefone,r.email FROM consulta c JOIN dependente d ON d.id=c.dependente_id JOIN responsavel r ON r.id=d.responsavel_id ORDER BY c.data_consulta,c.horario";try(Connection c=Conexao.conectar();PreparedStatement s=c.prepareStatement(q)){s.setString(1,CHAVE_AES);try(ResultSet rs=s.executeQuery()){while(rs.next()){Consulta a=new Consulta();a.setId(rs.getInt("id"));a.setDependenteId(rs.getInt("dependente_id"));a.setDataConsulta(rs.getDate("data_consulta"));a.setHorario(rs.getTime("horario"));a.setMotivo(rs.getString("motivo"));a.setNomeDependente(rs.getString("dependente"));a.setNascimentoDependente(rs.getDate("data_nascimento"));a.setSexoDependente(rs.getString("sexo"));a.setAlergiasDependente(rs.getString("alergias"));a.setNomeResponsavel(rs.getString("responsavel"));a.setCpfResponsavel(rs.getString("cpf_responsavel"));a.setTelefoneResponsavel(rs.getString("telefone"));a.setEmailResponsavel(rs.getString("email"));l.add(a);}}}catch(Exception e){System.out.println("Erro ao listar consultas: "+e.getMessage());}return l;}
}